import { useState, type ReactElement } from 'react';

export type Row = { id: string; label: string; score: number | null };
export type Props = { rows: Row[] };

type Direction = 'none' | 'ascending' | 'descending';
type IndexedRow = { row: Row; index: number };

function orderRows(rows: Row[], direction: Direction): Row[] {
  if (direction === 'none') return [...rows];

  const indexed: IndexedRow[] = rows.map(
    (row: Row, index: number): IndexedRow => ({ row, index }),
  );

  indexed.sort((left: IndexedRow, right: IndexedRow): number => {
    const a: number | null = left.row.score;
    const b: number | null = right.row.score;
    if (a === null && b === null) return left.index - right.index;
    if (a === null) return 1;
    if (b === null) return -1;

    const difference: number = direction === 'ascending' ? a - b : b - a;
    return difference === 0 ? left.index - right.index : difference;
  });

  return indexed.map((entry: IndexedRow): Row => entry.row);
}

export function Component({ rows }: Props): ReactElement {
  const [direction, setDirection] = useState<Direction>('none');
  const displayedRows: Row[] = orderRows(rows, direction);

  function toggleSort(): void {
    setDirection((current: Direction): Direction =>
      current === 'ascending' ? 'descending' : 'ascending',
    );
  }

  return (
    <div
      data-testid="panel"
      style={{
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#f2f6fc',
        color: '#1d3150',
        padding: 16,
        gap: 8,
      }}
    >
      <button type="button" onClick={toggleSort}>Sort score</button>
      <table aria-label="Rows">
        <thead>
          <tr>
            <th scope="col">Label</th>
            <th scope="col" aria-sort={direction}>Score</th>
          </tr>
        </thead>
        <tbody>
          {displayedRows.map((row: Row): ReactElement => (
            <tr key={row.id}>
              <td>{row.label}</td>
              <td>{row.score === null ? '—' : row.score}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {rows.length === 0 && <p role="status">No rows</p>}
    </div>
  );
}
